export type Score = {id:string;name:string;path:string;netWorth:number;cash:number;value:number;debt:number;ownership:number;date:string};
export const MAX_TURNS=10;
export const ANNUAL_ASSET_CASHFLOW_RATE=0.10;
/** Annual operating cash generated by productive assets; cash is excluded from the base. */
export function annualAssetCashFlow(value:number){return Math.round(Math.max(0,value)*ANNUAL_ASSET_CASHFLOW_RATE)}
