export function lifeChoices(g:Game){return g.pendingLife?lifeCards.filter(c=>c.career===g.path.id&&c.milestone===g.pendingLife):[]}
export function chooseLifeCard(game:Game,id:string){const g:Game=structuredClone(game);const c=lifeChoices(g).find(x=>x.id===id);if(!c)throw Error('Invalid Life Card');const before=netWorth(g);g.lifeCards=[...(g.lifeCards||[]),id];g.pendingLife=null;g.cash+=c.cashChange;g.debt+=c.debtChange;g.ownership=Math.max(.05,Math.min(1,Math.round((g.ownership+c.ownershipChange)*100)/100));g.risk=g.path.id==='unicorn'?0:Math.max(0,Math.min(100,g.risk+c.riskChange));const result:HistoryItem={turn:g.turn-1,card:c.name,message:`Life Card selected: ${c.benefit}. All benefits are permanent.`,delta:netWorth(g)-before,lesson:'Career choices have lasting consequences.'};g.history.unshift(result);draw(g);g.round++;return {game:g,result}}
export function lifeGrowth(g:Game){return Math.max(.3,1+lifeCards.filter(c=>(g.lifeCards||[]).includes(c.id)).reduce((sum,c)=>sum+c.growth,0))}
export function lifeYield(g:Game){return Math.max(0,.1+lifeCards.filter(c=>(g.lifeCards||[]).includes(c.id)).reduce((sum,c)=>sum+c.yieldBonus,0))}
export type Turmoil = {id:string;name:string;inspiration:string;description:string;cashLoss:number;assetLoss:number;debtIncrease:number;riskIncrease:number};
