export type RecoveryChoice = 'liquidity'|'restructure'|'rebuild';
export function resolveTurmoil(game:Game,choice:RecoveryChoice):{game:Game;result:HistoryItem}{
if(!game.pendingTurmoil||!game.turmoilId)throw Error('No pending turmoil');
const g=structuredClone(game),before=netWorth(g);let message='';
if(choice==='liquidity'){const raised=Math.round(Math.max(10000,g.value*.12));g.cash+=raised;g.debt+=raised;g.risk=g.path.id==='unicorn'?0:Math.min(100,g.risk+7);message=`Emergency credit adds ${fmt(raised)} cash and equal debt. Interest continues.`;}
else if(choice==='restructure'){const sale=Math.round(g.value*.18);g.value-=sale;g.cash+=Math.round(sale*.85);g.risk=g.path.id==='unicorn'?0:Math.max(0,g.risk-12);message=`Sold ${fmt(sale)} of business assets at a 15% discount to rebuild liquidity; risk reduced.`;}
else{const spend=Math.min(g.cash,Math.round(Math.max(2500,g.value*.04)));g.cash-=spend;g.value+=Math.round(spend*1.4);g.skill=Math.min(100,g.skill+4);g.risk=g.path.id==='unicorn'?0:Math.max(0,g.risk-5);message=`Invested ${fmt(spend)} in a turnaround, increasing assets and skill while lowering risk.`;}
g.pendingTurmoil=false;g.turmoilResolved=true;draw(g);g.round++;
const result:HistoryItem={turn:5,card:'Turmoil Recovery',message,delta:netWorth(g)-before,lesson:'Surviving a crisis requires balancing liquidity, leverage, and long-term operating capacity.'};g.history.unshift(result);return {game:g,result};
}
